'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isSameComplex64Array = require( '@stdlib/assert/is-same-complex64array' );
var Complex64Array = require( '@stdlib/array/complex64' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var cediff = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( cediff instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cediff, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 15', opts, function test( t ) {
	t.strictEqual( cediff.length, 15, 'returns expected value' );
	t.end();
});

tape( 'the function calculates differences between consecutive elements of a single-precision complex floating-point strided array', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	x = new Complex64Array([
		2.0,
		3.0,
		4.0,
		7.0,
		6.0,
		11.0,
		8.0,
		15.0,
		10.0,
		19.0
	]);
	p = new Complex64Array([
		1.0,
		2.0
	]);
	a = new Complex64Array([
		11.0,
		21.0
	]);
	out = new Complex64Array( 6 );

	cediff( x.length, x, 1, 0, 1, p, 1, 0, 1, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		1.0,
		2.0,
		2.0,
		4.0,
		2.0,
		4.0,
		2.0,
		4.0,
		2.0,
		4.0,
		11.0,
		21.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns the output array unchanged', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	x = new Complex64Array([
		2.0,
		-2.0,
		4.0,
		-4.0
	]);
	p = new Complex64Array( 0 );
	a = new Complex64Array( 0 );
	out = new Complex64Array( 2 );

	cediff( 0, x, 1, 0, 0, p, 1, 0, 0, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		0.0,
		0.0,
		0.0,
		0.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	cediff( -4, x, 1, 0, 0, p, 1, 0, 0, a, 1, 0, out, 1, 0 );
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'if the sum of the `N`, `N1`, and `N2` parameters is less than or equal to `1`, the function returns the output array unchanged', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	x = new Complex64Array([
		5.0,
		-5.0
	]);
	p = new Complex64Array( 0 );
	a = new Complex64Array( 0 );
	out = new Complex64Array( 1 );

	cediff( 1, x, 1, 0, 0, p, 1, 0, 0, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		0.0,
		0.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

