tape( 'the function supports multiple prepend and append values', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	// Prepend (N1=2), x, and append (N2=2):
	x = new Complex64Array([
		5.0,
		-5.0
	]);
	p = new Complex64Array([
		1.0,
		-1.0,
		3.0,
		-3.0
	]);
	a = new Complex64Array([
		7.0,
		-7.0,
		9.0,
		-9.0
	]);
	out = new Complex64Array( 4 );

	cediff( x.length, x, 1, 0, 2, p, 1, 0, 2, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		1.0,
		-1.0,
		3.0,
		-3.0,
		7.0,
		-7.0,
		9.0,
		-9.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	// Prepend (N1=2) and append (N2=2), no x:
	x = new Complex64Array( 0 );
	out = new Complex64Array( 4 );

	cediff( 0, x, 1, 0, 2, p, 1, 0, 2, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		1.0,
		-1.0,
		3.0,
		-3.0,
		7.0,
		-7.0,
		9.0,
		-9.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

