tape( 'the function supports multiple append values without prepend', opts, function test( t ) {
	var expected;
	var out;
	var x;
	var p;
	var a;

	// No prepend, x present, multiple append (N2=3):
	x = new Complex64Array([
		2.0,
		-2.0,
		5.0,
		-5.0
	]);
	p = new Complex64Array( 0 );
	a = new Complex64Array([
		10.0,
		-10.0,
		13.0,
		-13.0,
		18.0,
		-18.0
	]);
	out = new Complex64Array( 4 );

	cediff( x.length, x, 1, 0, 0, p, 1, 0, 3, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		3.0,
		-3.0,
		10.0,
		-10.0,
		13.0,
		-13.0,
		18.0,
		-18.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );

	// Append only (no prepend, no x):
	x = new Complex64Array( 0 );
	out = new Complex64Array( 3 );

	cediff( 0, x, 1, 0, 0, p, 1, 0, 3, a, 1, 0, out, 1, 0 );

	expected = new Complex64Array([
		10.0,
		-10.0,
		13.0,
		-13.0,
		18.0,
		-18.0
	]);
	t.strictEqual( isSameComplex64Array( out, expected ), true, 'returns expected value' );
	t.end();
});

